// Do not edit: this file is rewritten on every osl generate.

"use client";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Link, Outlet, useMatchRoute, useNavigate, useParams } from "@tanstack/react-router";
import { Plus } from "lucide-react";
import { Fragment, useEffect, useState, type FormEvent } from "react";
import { Button, buttonVariants } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { client, sessionUser, type Inputs, type Outputs, type SessionUser } from "../client";
import { EmptyPane, ErrorNote, FieldRow, FormRow, ListSkeleton, Pagination, Pane, PaneHeader, PaneSkeleton, formatDateTime, splitList, text } from "../ui";

type Row = Outputs["artists"]["list"]["data"][number];
type Detail = Outputs["artists"]["get"];
type Input<K extends keyof Inputs["artists"]> = Inputs["artists"][K];

const PAGE_SIZE = 20;
const KEY = ["artists"] as const;

function idOf(raw: string) {
  return raw;
}

function canCreate(user: SessionUser | null): boolean {
  return user !== null;
}

function canUpdate(user: SessionUser | null, row: Detail): boolean {
  return user !== null && row.owner_id === user.id;
}

function canDelete(user: SessionUser | null, row: Detail): boolean {
  return user !== null && row.owner_id === user.id;
}

const ARTISTS_FIELDS = ["name"] as const;
type ArtistsField = (typeof ARTISTS_FIELDS)[number];

type ArtistsValues = {
  name: string;
};

const EMPTY_ARTISTS: ArtistsValues = {
  name: ""
};

const ARTISTS_CREATE: readonly ArtistsField[] = ["name"];

function toArtistsCreateInput(v: ArtistsValues): Input<"create"> {
  return {
    name: v.name
  };
}

const ARTISTS_UPDATE: readonly ArtistsField[] = ["name"];

function toArtistsUpdateInput(v: ArtistsValues): Input<"update">["data"] {
  return {
    name: v.name
  };
}

function artistsFromRow(row: Detail): ArtistsValues {
  return {
    name: text(row.name)
  };
}

type ArtistsSetter = <K extends keyof ArtistsValues>(key: K, value: ArtistsValues[K]) => void;

function renderArtistsField(field: ArtistsField, values: ArtistsValues, set: ArtistsSetter) {
  switch (field) {
    case "name":
      return (
      <FormRow label="Name" htmlFor="name">
        <Input id="name" type="text" maxLength={120} value={values.name} onChange={e => set("name", e.target.value)} required />
      </FormRow>
      );
  }
}

function ArtistsForm({
  fields,
  initial,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly ArtistsField[];
  initial: ArtistsValues;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: ArtistsValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<ArtistsValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: ArtistsSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderArtistsField(field, values, set)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

export function ArtistsLayout() {
  const [page, setPage] = useState(1);
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const input = { page, page_size: PAGE_SIZE } as Inputs["artists"]["list"];
  const list = useQuery({ queryKey: [...KEY, "list", input], queryFn: () => client.artists.list(input) });
  const matchRoute = useMatchRoute();
  const queryClient = useQueryClient();

  return (
    <div className="flex h-full min-h-0">
      <aside className="flex w-80 shrink-0 flex-col border-r border-border">
        <PaneHeader title="Artists" count={list.data?.page.total}>
          {canCreate(user) ? (
            <Link to="/artists/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New artist">
              <Plus />
            </Link>
          ) : null}
        </PaneHeader>


        <div className="min-h-0 flex-1 overflow-y-auto">
          {list.isPending ? (
            <ListSkeleton />
          ) : list.error ? (
            <ErrorNote error={list.error} className="m-4" />
          ) : list.data.data.length === 0 ? (
            <EmptyPane>No artists yet.</EmptyPane>
          ) : (
            <ul className="py-1">
              {list.data.data.map((row: Row) => (
                <li key={text(row.id)}>
                  <Link
                    to="/artists/$id" params={{ id: text(row.id) }}
                    className={cn("block border-l-2 border-transparent px-4 py-2 hover:bg-accent/60", Boolean(matchRoute({ to: "/artists/$id", params: { id: text(row.id) } })) && "border-primary bg-accent")}
                  >
                    <div className="truncate text-sm font-medium">{text(row.name) || "Artist " + text(row.id)}</div>
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </div>
        {list.data ? <Pagination page={page} pageSize={PAGE_SIZE} total={list.data.page.total} onChange={setPage} /> : null}
      </aside>
      <section className="min-w-0 flex-1 overflow-y-auto">
        <Outlet />
      </section>
    </div>
  );
}

export function ArtistsIndex() {
  return <EmptyPane>Select an artist from the list, or create one.</EmptyPane>;
}

export function ArtistsNew() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.artists.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/artists/$id", params: { id: text(row.id) } });
    }
  });
  return (
    <Pane title="New artist">
      <ArtistsForm
        fields={ARTISTS_CREATE}
        initial={EMPTY_ARTISTS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toArtistsCreateInput(values))}
      />
    </Pane>
  );
}

export function ArtistsDetail() {
  const { id: rawId } = useParams({ from: "/artists/$id" });
  const id = idOf(rawId);
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  useEffect(() => {
    setEditing(false);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.artists.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["artists"]["update"]) => client.artists.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["artists"]["delete"]) => client.artists.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/artists" });
    }
  });

  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.name) || "Artist " + text(row.id)}
      actions={
        <>
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this artist?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >


      {editing ? (
        <ArtistsForm
          fields={ARTISTS_UPDATE}
          initial={artistsFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toArtistsUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Owner">{text(row.owner_id) || "—"}</FieldRow>
        <FieldRow label="Name">{text(row.name) || "—"}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        <FieldRow label="Albums">
          {row.albums.length === 0 ? (
            "—"
          ) : (
            <ul className="space-y-1">
              {row.albums.map(item => (
                <li key={text(item.id)}>{text(item.title)}</li>
              ))}
            </ul>
          )}
        </FieldRow>
        </dl>
      )}
    </Pane>
  );
}
